def ab_test_outcome(control_group, treatment_group):
    from scipy import stats
    t_stat, p_value = stats.ttest_ind(control_group, treatment_group)
    if p_value < 0.05 and np.mean(treatment_group) > np.mean(control_group):
        return "Roll out treatment"
    else:
        return "Keep control or iterate"

