def calculate_pirate_health(data):
    acquisition_cac = data['mktg_spend'] / data['new_users']
    activation_rate = data['activated'] / data['new_users']
    retention_rate = data['users_active_day30'] / data['users_active_day0']
    ltv = data['avg_monthly_revenue'] * (1 / data['churn_rate'])
    referral_viral = data['invites_sent'] * data['invite_conversion']
    return {
        'CAC_ltv_ratio': ltv / acquisition_cac,
        'pirate_score': (activation_rate * retention_rate * (1 + referral_viral)) / (acquisition_cac / 10)
    }

