# Score your interview questions
def mom_test_score(question_text):
    bad_patterns = ['would you', 'do you think', 'do you like', 'in the future']
    good_patterns = ['last time', 'show me', 'how much', 'when did', 'what did you do']
    score = 0
    for pattern in bad_patterns:
        if pattern in question_text.lower():
            score -= 1
    for pattern in good_patterns:
        if pattern in question_text.lower():
            score += 2
    if score >= 2: return "Pass (Mom Test safe)"
    elif score < 0: return "Fail — likely to get lies"
    else: return "Neutral — add more specific past-behavior prompts"

