def debrief_forced_negatives(interview_notes):
    """Extract only critical points from interview"""
    negatives = []
    for note in interview_notes.split('. '):
        if any(neg in note.lower() for neg in ['not', "doesn't", 'never', 'fail', 'bad', 'struggle']):
            negatives.append(note)
    if len(negatives) < 3:
        print("WARNING: Low critical feedback — possible polite lies")
    return negatives

