# Compare attribution models on a sample journey
def attribute_conversion(touchpoints, model):
    n = len(touchpoints)
    if model == 'last_click':
        return {touchpoints[-1]: 1.0}
    elif model == 'first_click':
        return {touchpoints[0]: 1.0}
    elif model == 'linear':
        equal = 1.0 / n
        return {t: equal for t in touchpoints}
    elif model == 'time_decay':
        # exponential decay: later touches more weight
        weights = [2**i for i in range(n)]
        total = sum(weights)
        return {t: w/total for t,w in zip(touchpoints, weights)}
    elif model == 'position_based':
        if n == 1:
            return {touchpoints[0]: 1.0}
        first_last = 0.4
        middle = (0.2) / (n-2) if n > 2 else 0
        attribution = {}
        for i, t in enumerate(touchpoints):
            if i == 0: attribution[t] = first_last
            elif i == n-1: attribution[t] = first_last
            else: attribution[t] = middle
        return attribution

