# Brief Resilience Scale (BRS) scoring
def calculate_brs(responses):
    """responses: list of 6 integers (1=Strongly disagree to 5=Strongly agree)
       Items 2,4,6 are reverse-scored."""
    # Reverse score items 2,4,6 (index 1,3,5 in 0-based)
    for idx in [1,3,5]:
        responses[idx] = 6 - responses[idx]
    total = sum(responses)
    mean = total / 6
    if mean >= 4.3:
        return "Normal resilience"
    elif mean >= 3.0:
        return "Low resilience"
    else:
        return "Very low resilience — consider therapy referral"

# Example: [4, 2, 5, 1, 3, 4] -> after reverse = [4,4,5,5,3,2] -> total=23, mean=3.83 -> Low

def pivot_decision(confidence_score, runway_months):
    """confidence_score: 0-1, runway_months: float"""
    if confidence_score > 0.7 and runway_months > 6:
        return "Persevere — keep executing"
    elif confidence_score > 0.7 and runway_months <= 6:
        return "Accelerate — double down (hire, spend)"
    elif confidence_score <= 0.7 and runway_months > 6:
        return "Pivot — run 2-week experiment"
    else:
        return "Harvest — seek acqui-hire or shut down"

